          "userId": "eid_890654c4",
          "timestamp": "2026-04-11T10:16:00",
          "text": "Hi team, I've shared the <https://sf-internal.slack.com/archives/docs/cofoaix_market_research_report|Market Research Report> for CoFoAIX. Let's discuss any feedback or suggestions you might have to refine it further. 😊",
          "utterranceID": "20260411-0-78bc2"
